import json,hashlib,collections,re
from pathlib import Path
from datetime import datetime,timezone
ROOT=Path(__file__).resolve().parent.parent;HERE=ROOT/'full-game/runtime-visuals'
read=lambda p:json.loads(p.read_text(encoding='utf-8-sig'))
m=read(HERE/'manifest.json');errors=[]
reasons={'.woff':'Preserve localized text coverage and text metrics; Daoist styling is provided by the surrounding panels and imagery. These fonts are not newly drawn art.', '.ttf':'Preserve runtime glyph codepoints and metrics for technical symbols, logic text and icon-font fallbacks. Styled bitmap icons are delivered separately; this font is retained, not represented as redesigned.', '.frag':'Preserve the renderer program for runtime color, lighting, fog, heat, shield and fluid effects; authored texture inputs are mapped separately.', '.vert':'Preserve geometry projection, lighting coordinates and GPU input contracts; this is executable rendering code, not a bitmap asset.'}
for a in m['assets']:
    p=ROOT/a['file'];data=p.read_bytes()
    if hashlib.sha256(data).hexdigest()!=a['sha256']:errors.append('hash:'+a['file'])
    if hashlib.sha1(b'blob '+str(len(data)).encode()+b'\0'+data).hexdigest()!=a['sourceGitBlob']:errors.append('git_blob:'+a['file'])
    a['reason']=reasons[p.suffix];a['status']='exact_reuse_verified_runtime_unverified'
cfg=read(HERE/'upstream/core/assets-raw/fontgen/config.json')
glyphs=[{'name':g['css'],'codepoint':g['code'],'sourceFamily':g.get('src'),'disposition':'existing_font_glyph_retained','reason':'Codepoint-compatible monochrome symbol fallback; styled atlas images do not automatically replace font glyphs.'}for g in cfg['glyphs']]
planets=(HERE/'upstream/core/src/mindustry/content/Planets.java').read_text()
planetNames=re.findall(r'new Planet\("([^"]+)"',planets)
families=[
 {'id':'localized-fonts','evidence':'core/src/mindustry/ui/Fonts.java','disposition':'exact_upstream_font_reuse','details':'Main/Japanese text, monospace logic, icon and tech fonts retain readable glyphs and original metrics.'},
 {'id':'planet-surfaces-clouds-atmosphere','evidence':'core/src/mindustry/content/Planets.java','disposition':'retain_mesh_algorithms_and_palettes','details':'Sun, Serpulo, Erekir, Tantros and asteroid meshes are generated from geometry/noise, not omitted image files. Their original functional surface palettes and geometry remain. Campaign emblems and space cubemap are provided by the art domains.','planetConstructorNames':planetNames},
 {'id':'lighting-fog-fluids-shields','evidence':'core/src/mindustry/graphics/Shaders.java','disposition':'exact_shader_reuse','details':'41 shader files retained. New source textures remain separate, preserving sampler names and runtime tint behavior.'},
 {'id':'267-runtime-fx-callbacks','evidence':'full-game/items-fx/runtime-fx.json','disposition':'retain_exact_official_callbacks','details':'Primitive circles, rays, dust, smoke, lightning and explosions retain official drawing algorithms and gameplay parameters. All texture dependencies have explicit source mappings.'},
 {'id':'128-build-time-fluid-and-particle-regions','evidence':'full-game/items-fx/runtime-atlas.json','disposition':'preserve_official_generator_contract','details':'16 bubble and 12 splash masks exported; 50 liquid and 50 gas regions generated by preserved official algorithm.'},
 {'id':'block-and-unit-runtime-transforms','evidence':'full-game/blocks/inventory.json','disposition':'keep_original_renderer_transforms','details':'Rotation, recoil, legs, tread frames, draw-part loops and moving pistons consume the new original-canvas layers. Their renderer is not a separate missing art sheet.'},
 {'id':'world-layout-and-map-data','evidence':'records/reference-ui-sources/official-tree-v160.7.json','disposition':'keep_original_map_and_generator_data','details':'114 msav files are binary gameplay maps, not images. Source content layouts, procedural world generators and map saves are preserved in the upstream game; no map save is represented as new art.'}
]
review={'checkedAt':datetime.now(timezone.utc).isoformat(),'status':'technical_dependencies_and_procedural_families_reviewed','sourceCommit':m['sourceCommit'],'counts':dict(collections.Counter(Path(a['sourcePath']).suffix for a in m['assets'])),'fontGlyphCount':len(glyphs),'fontGlyphs':glyphs,'families':families,'errors':errors,'runtimeIntegrationVerified':False,'scopeLimitation':'These dependencies are explicitly reused. This package does not claim that every font outline, procedural particle or 3D mesh has been redrawn in the Daoist style.'}
(HERE/'review.json').write_text(json.dumps(review,ensure_ascii=False,indent=2)+'\n',encoding='utf-8');m['status']='complete_exact_technical_reuse';m['review']='full-game/runtime-visuals/review.json';(HERE/'manifest.json').write_text(json.dumps(m,indent=2)+'\n',encoding='utf-8')
print(json.dumps({k:review[k]for k in ['status','counts','fontGlyphCount','errors']}));assert not errors
